SELECT ba.apply_id, ba.apply_no, ba.budget_year, ba.item_id, ba.item_code, ba.item_name, ba.subject_id, ba.subject_code, ba.subject_name, ba.apply_amount, ba.apply_reason, ba.status, ba.process_definition_id, ba.process_instance_id, ba.applicant_id, ba.applicant_code, ba.applicant_name, ba.dept_id, ba.dept_code, COALESCE(d.dept_name, ba.dept_name, '') AS dept_name, COALESCE(ba.applicant_phone, e.emp_phone, '') AS applicant_phone, ba.template_config_id, ba.main_attach_id, ba.apply_date, ba.create_user, ba.create_time, ba.update_time FROM budget_apply ba LEFT JOIN sys_emp e ON ba.applicant_id = e.emp_id LEFT JOIN sys_dept d ON ba.dept_id = d.dept_id
AND ba.apply_no LIKE CONCAT('%', #{applyNo}, '%')
AND ba.item_id = #{itemId}
AND ba.applicant_name LIKE CONCAT('%', #{applicantName}, '%')
AND ba.applicant_code = #{applicantCode}
AND ba.status = #{status}
AND DATE(ba.apply_date) >= #{startDate}
AND DATE(ba.apply_date) <= #{endDate}
ORDER BY ba.create_time DESC

SELECT ba.apply_id, ba.apply_no, ba.budget_year, ba.item_id, ba.item_code, ba.item_name, ba.subject_id, ba.subject_code, ba.subject_name, ba.apply_amount, ba.apply_reason, ba.status, ba.process_definition_id, ba.process_instance_id, ba.applicant_id, ba.applicant_code, ba.applicant_name, ba.dept_id, ba.dept_code, COALESCE(d.dept_name, ba.dept_name, '') AS dept_name, COALESCE(ba.applicant_phone, e.emp_phone, '') AS applicant_phone, ba.template_config_id, ba.main_attach_id, ba.apply_date, ba.create_user, ba.create_time, ba.update_time FROM budget_apply ba LEFT JOIN sys_emp e ON ba.applicant_id = e.emp_id LEFT JOIN sys_dept d ON ba.dept_id = d.dept_id WHERE ba.item_id = #{itemId} AND ba.subject_id = #{subjectId} AND ba.budget_year = #{budgetYear}
AND ba.apply_id != #{excludeApplyId}
LIMIT 1

