UPDATE budget_apply
apply_no = #{applyNo}, budget_year = #{budgetYear}, item_id = #{itemId}, item_code = #{itemCode}, item_name = #{itemName}, subject_id = #{subjectId}, subject_code = #{subjectCode}, subject_name = #{subjectName}, apply_amount = #{applyAmount}, apply_reason = #{applyReason}, status = #{status}, process_definition_id = #{processDefinitionId}, process_instance_id = #{processInstanceId}, template_config_id = #{templateConfigId}, main_attach_id = #{mainAttachId}, apply_date = #{applyDate}, update_time = #{updateTime},
WHERE apply_id = #{applyId}
